import{_ as a,c as t,o as n,ae as s}from"./chunks/framework.CliRSA9F.js";const p=JSON.parse('{"title":"Teams and Organizations","description":"Set up a PodSEO team, invite colleagues, assign podcast access, and understand roles and seat limits.","frontmatter":{"description":"Set up a PodSEO team, invite colleagues, assign podcast access, and understand roles and seat limits."},"headers":[],"relativePath":"features/teams-and-organizations.md","filePath":"features/teams-and-organizations.md"}'),i={name:"features/teams-and-organizations.md"};function o(r,e,d,c,h,m){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="teams-and-organizations" tabindex="-1">Teams and Organizations <a class="header-anchor" href="#teams-and-organizations" aria-label="Permalink to &quot;Teams and Organizations&quot;">​</a></h1><p>Use a team workspace when several people manage the same podcasts. Each person signs in with their own login, while the organization shares its podcasts, plan allowances, and billing.</p><h2 id="set-up-your-team" tabindex="-1">Set up your team <a class="header-anchor" href="#set-up-your-team" aria-label="Permalink to &quot;Set up your team&quot;">​</a></h2><p>Open <strong>Settings → Team</strong> and choose <strong>Set up your team</strong>. Team setup requires an account with more than one available seat. Producer includes 2 seats, Agency includes 20, and Enterprise has no fixed seat cap. Free and Podcaster include 1 seat. Upgrade for initial team setup; existing paid organization accounts can purchase extra seats through <a href="/features/billing-and-account.html">Billing and account settings</a>.</p><p>Once your workspace exists, owners and admins manage invitations from <strong>Organization settings</strong>. Switch to the organization account when working on shared shows; your personal account and organization are separate contexts.</p><h2 id="invite-someone-and-choose-their-access" tabindex="-1">Invite someone and choose their access <a class="header-anchor" href="#invite-someone-and-choose-their-access" aria-label="Permalink to &quot;Invite someone and choose their access&quot;">​</a></h2><ol><li>Open <strong>Organization settings</strong>.</li><li>Enter the person&#39;s email address and choose their role.</li><li>For restricted access, select the specific podcasts they should work on.</li><li>Send the invitation. The recipient follows the invitation link and signs in to accept it.</li></ol><table tabindex="0"><thead><tr><th>Role</th><th>What it is for</th></tr></thead><tbody><tr><td>Owner</td><td>Owns and administers the organization. The owner of a self-service workspace remains its owner.</td></tr><tr><td>Admin</td><td>Manages team members and has access to all organization podcasts.</td></tr><tr><td>Member</td><td>Works on podcast content and settings within their assigned access, without administering the team.</td></tr><tr><td>Viewer</td><td>Views accessible podcast information without editing it; may respond to reviews assigned to them in the Agency workspace.</td></tr></tbody></table><p>Owners and admins have organization-wide access. Use Member or Viewer access for collaborators who should only see selected shows. In the Agency workspace, client viewers only see assigned podcasts and the reports made available to them.</p><h2 id="seats-invitations-and-removing-access" tabindex="-1">Seats, invitations, and removing access <a class="header-anchor" href="#seats-invitations-and-removing-access" aria-label="Permalink to &quot;Seats, invitations, and removing access&quot;">​</a></h2><p>Active members and pending invitations consume seats. Your seat limit is your plan&#39;s included seats plus any seat add-ons you&#39;ve purchased. If an invitation is blocked by your limit, review outstanding invitations before buying more capacity. Manage roles, invitations, and podcast assignments in Organization settings; removing someone&#39;s access does not require sharing or changing another person&#39;s login.</p><p>To reduce paid seat capacity, first bring your active membership and pending invitations within the lower limit. PodSEO won&#39;t remove a seat add-on while those seats are in use; instead you&#39;ll see how many seats your team uses (including pending invitations) and how many team members to remove first. An extra seat increases team capacity; it does not create another keyword or credit allowance.</p><h3 id="what-happens-to-my-team-if-we-downgrade" tabindex="-1">What happens to my team if we downgrade? <a class="header-anchor" href="#what-happens-to-my-team-if-we-downgrade" aria-label="Permalink to &quot;What happens to my team if we downgrade?&quot;">​</a></h3><p>If a plan downgrade leaves your team with more people than the new plan&#39;s seat limit, PodSEO brings the team back within the limit: pending invitations are cancelled, and if there are still too many members, the excess members are removed from the organization, starting with the lowest-privilege roles (Viewers first). The owner is never removed. Removed members receive an email letting them know. To choose who keeps access yourself, remove members before you downgrade.</p><h2 id="why-can-t-a-teammate-see-a-podcast" tabindex="-1">Why can&#39;t a teammate see a podcast? <a class="header-anchor" href="#why-can-t-a-teammate-see-a-podcast" aria-label="Permalink to &quot;Why can&#39;t a teammate see a podcast?&quot;">​</a></h2><p>Check that they accepted the invitation, selected the organization account, and have the right podcast assignment. A role change or removed assignment can also remove access. Ask an owner or admin to correct assignments rather than sharing credentials.</p><p>Agency teams can use <a href="/features/agency-workspace.html">client reports and approvals</a> to get feedback without giving clients editing access. Keep client assignments narrow and review them when an engagement ends.</p>',17)])])}const g=a(i,[["render",o]]);export{p as __pageData,g as default};
